#!/usr/bin/env node
// 把 shiguang-schedule 的 model.js + ui.js 拼成插件入口 main.js，并把 CPPU 适配脚本复制到插件目录。
// main.js 是生成物（插件加载器只认它），手工改它会在下次构建被覆盖 —— 这也是它头顶写着
// “Generated by tools/build-schedule-plugin.js” 的原因。
//
// --check：只校验、不写盘，供 npm test / CI 拦住「改了源忘了重新生成」。
const fs=require('fs');
const path=require('path');
const CHECK=process.argv.includes('--check');
const miniModels=require('./sync-miniprogram-models.js');
const root=path.resolve(__dirname,'..');
const dir=path.join(root,'le-time-management','public','plugins','shiguang-schedule');
const adapterDir=path.join(dir,'adapters');
const cppuAdapter=path.join(root,'vendor','shiguangschedule','shared','assets','offline_repo','schools','resources','CPPU','cppu.js');
let model=fs.readFileSync(path.join(dir,'model.js'),'utf8');
model=model.replace(/\}\)\(typeof module!==['"]undefined['"]\?module\.exports:globalThis\);\s*$/, '})(modelScope);');
const ui=fs.readFileSync(path.join(dir,'ui.js'),'utf8');
const combined=`// Generated by tools/build-schedule-plugin.js; edit model.js / ui.js.\n(function(){const modelScope={};\n${model}\n${ui}\n})();\n`;
const mainPath=path.join(dir,'main.js');
if(CHECK){
  const failures=[];
  try{miniModels.sync({check:true});}catch(error){failures.push(error.message);}
  const current=fs.existsSync(mainPath)?fs.readFileSync(mainPath,'utf8'):'';
  if(current!==combined)failures.push('main.js 与 model.js + ui.js 不一致');
  const adapterPath=path.join(adapterDir,'cppu.js');
  const adapterSource=fs.readFileSync(cppuAdapter,'utf8');
  if(!fs.existsSync(adapterPath)||fs.readFileSync(adapterPath,'utf8')!==adapterSource)failures.push('adapters/cppu.js 与 vendor 里的源不一致');
  if(failures.length){
    console.error('shiguang-schedule 生成物检查失败：');
    failures.forEach(x=>console.error('- '+x));
    console.error('请运行：node tools/build-schedule-plugin.js');
    process.exit(1);
  }
  console.log('✓ shiguang-schedule 生成物与源一致');
  process.exit(0);
}
fs.writeFileSync(mainPath,combined,'utf8');
fs.mkdirSync(adapterDir,{recursive:true});
fs.copyFileSync(cppuAdapter,path.join(adapterDir,'cppu.js'));
miniModels.sync();
console.log('✓ rebuilt shiguang-schedule/main.js and shared miniprogram models');
